<script>document.addEventListener('click',e=>{const remove=e.target.closest('.b-remove');if(remove){remove.parentElement.remove();return}const add=e.target.closest('[data-add]');if(!add)return;let type=add.dataset.add,box=document.getElementById(type+'s'),i=box.children.length,html='';if(type==='ticket')html=`<div class="b-row"><input name="tickets[${i}][name]" placeholder="e.g. General admission" aria-label="Ticket name" required><input type="number" step=".01" min="0" name="tickets[${i}][price]" value="0" placeholder="0.00" aria-label="Price"><input type="number" min="1" name="tickets[${i}][capacity]" placeholder="Unlimited" aria-label="Capacity"><input type="number" min="1" name="tickets[${i}][maximum_per_order]" value="10" aria-label="Maximum per booking"><button type="button" class="b-remove" title="Remove ticket">×</button><input type="hidden" name="tickets[${i}][is_active]" value="1"></div>`;if(type==='addon')html=`<div class="b-row addon"><input name="addons[${i}][name]" placeholder="e.g. Vegetarian lunch" aria-label="Option name"><select name="addons[${i}][category]" aria-label="Category"><option value="food">Food</option><option value="merchandise">Merchandise</option><option value="other">Other</option></select><input type="number" step=".01" min="0" name="addons[${i}][price]" value="0" placeholder="0.00" aria-label="Price"><select name="addons[${i}][pricing_type]" aria-label="Charging method"><option value="per_seat">Per attendee</option><option value="per_order">Per booking</option></select><button type="button" class="b-remove" title="Remove option">×</button><input type="hidden" name="addons[${i}][is_active]" value="1"></div>`;if(type==='field')html=`<div class="b-row field"><input name="fields[${i}][label]" placeholder="e.g. Dietary requirements" aria-label="Question"><select name="fields[${i}][field_type]" aria-label="Answer type"><option value="text">Short text</option><option value="email">Email</option><option value="phone">Phone</option><option value="textarea">Long text</option><option value="select">Dropdown choice</option><option value="checkbox">Yes / no</option></select><input name="fields[${i}][options]" placeholder="e.g. Yes, No, Maybe" aria-label="Dropdown choices"><select name="fields[${i}][applies_to]" aria-label="Who answers"><option value="order">Lead booker</option><option value="attendee">Each attendee</option></select><button type="button" class="b-remove" title="Remove question">×</button></div>`;box.insertAdjacentHTML('beforeend',html)});</script>
<script>document.getElementById('cover-image')?.addEventListener('change',function(){const file=this.files[0];if(!file)return;const preview=document.getElementById('cover-preview'),image=document.getElementById('cover-preview-image');image.src=URL.createObjectURL(file);image.style.display='block';const label=preview.querySelector('span');if(label)label.style.display='none'});</script>
<script>(()=>{document.querySelector('[name="allow_guest_registration"]')?.closest('label')?.remove();const box=document.getElementById('member-types'),attendees=document.getElementById('attendee-details-setting'),sync=()=>{const membersOnly=document.querySelector('[name="requires_login"]:checked')?.value==='1';box.style.display=membersOnly?'block':'none';attendees.style.display=membersOnly?'flex':'none'};document.querySelectorAll('[name="requires_login"]').forEach(r=>r.addEventListener('change',sync));sync()})();</script>
